-- BUG-29 切片1:补齐 schema 声明但迁移链缺失的 3 条普通索引(最小安全子集)。
-- 依据:静态对账(scratch/bug29-static-audit.md ③-A)—— 这 3 条索引在 src/schema 里
-- 已声明(agent-state.ts:114-115、chat.ts:195),但迁移链 drizzle/*.sql 无对应 CREATE INDEX,
-- 即"声明了但库上永不建成"。仅补普通二级索引:单表、无 FK、无跨表依赖、列类型 text/timestamp
-- 与建表一致(agent_meta_lessons 见 20260725140000、conversation_message_archives 见 20260901000000),
-- 不涉及 pending-review/20261106150000 那类 resource_downloads(user_id integer vs users.id uuid)类型不兼容坑。
-- 幂等:全部 IF NOT EXISTS;防长锁:单表小索引,生产可安全跑(不涉大表 CONCURRENTLY 需求)。
-- 隔离条件对照(见 drizzle-pending-review/20261106150000 头注):本切片只含索引、单件、不连坐 FK。

-- ① agent_meta_lessons:声明 agent-state.ts:114 index('agent_meta_lessons_user_type_idx').on(userId, lessonType)
CREATE INDEX IF NOT EXISTS "agent_meta_lessons_user_type_idx" ON "agent_meta_lessons" ("user_id", "lesson_type");

-- ② agent_meta_lessons:声明 agent-state.ts:115 index('idx_agent_meta_lessons_type_title').on(lessonType, title)
CREATE INDEX IF NOT EXISTS "idx_agent_meta_lessons_type_title" ON "agent_meta_lessons" ("lesson_type", "title");

-- ③ conversation_message_archives:声明 chat.ts:195 index('ix_conversation_message_archives_created_at').on(createdAt)
CREATE INDEX IF NOT EXISTS "ix_conversation_message_archives_created_at" ON "conversation_message_archives" ("created_at");
-- ⁠​‌​​‌​​‌‍‍​‌​​‌​​​‍‍​‌​‌​‌​‌‍‍​‌​​‌​​‌‍‍​​‌​‌‌​‌‍‍​‌​​​​​‌‍‍​‌​​‌​​‌‍‍‌​‌‌​‌‌‌‍‍‌‌​​‌‌​​‌‌‌‌​‌​‍‍‌‌​‌‌​​​‌​​​‌‌‌‍‍​‌​​​​​‌‍‍​‌​​‌​​‌‍‍‌​‌‌​‌‌‌‍‍‌‌​​‌‌‌​‌​​‌‌‌​‍‍‌‌​​‌‌​​​‌​​‌​‌‍‍‌​‌‌‌​‌‌‌​‌‌‌​‌‍‍‌​‌‌​‌‌‌‍‍​‌​​‌‌​​‍‍​‌​​​​‌‌‍‍‌​‌‌​‌‌‌‍‍​‌‌​​​​‌‍‍​‌‌​‌​​‌‍‍​‌‌‌‌​‌​‍‍​‌‌​‌​​​‍‍​‌‌‌​​‌‌‍‍​​‌​‌‌‌​‍‍​‌‌‌​‌​​‍‍​‌‌​‌‌‌‌‍‍​‌‌‌​​​​‍‍‌​‌‌​‌‌‌‍‍​‌​‌​​​​‍‍​‌​‌​​‌​‍‍​‌​​‌‌‌‌‍‍​‌​‌​‌‌​‍‍​‌​​​‌​‌‍‍​‌​​‌‌‌​‍‍​‌​​​​​‌‍‍​‌​​‌‌‌​‍‍​‌​​​​‌‌‍‍​‌​​​‌​‌‍‍​​‌​‌‌​‌‍‍​​‌‌​​‌​‍‍​​‌‌​​​​‍‍​​‌‌​​‌​‍‍​​‌‌​‌‌​⁠
